// pixelWorker.ts
// Web Worker: 원본 이미지를 받아 "픽셀아트" 스타일로 변환해 ImageBitmap을 반환한다.
//
// 포함 기능:
// - 자동 팔레트(K-means, 결정론적 시드) + 옵션: 디더링(Floyd–Steinberg)
// - 유사색 병합(ΔE76)로 팔레트 정리 → 더 깔끔한 컬러셋
// - 이음새 제거(seamless): 간격=0, 도트반지름=0(사각), 정수 스냅
// - 외곽선(경계선) 렌더: 공용 좌표(gx/gy) 기반 연속 구간 → 1px 라인이 끊기지 않음
// - 그리드(참고용) 렌더
//
// 메시지 타입:
// - "run": 변환 실행
// - "export-matrix": 마지막 변환의 색상 매트릭스(HEX)를 CSV용으로 반환

export {};

// ===== 타입 정의 =====
type PaletteMode = "none" | "localStorage" | "preset" | "autoK";

type RunPayload = {
    src: ImageBitmap;         // 변환할 원본 이미지 비트맵
    colCount: number;         // 가로 셀 개수
    rowCount: number;         // 세로 셀 개수

    gap: number;              // 도트 간격(px)
    dotRadius: number;        // 도트 반지름(px). 0이면 사각형

    palette: string[];        // 외부에서 전달된 팔레트(없으면 자동/none 사용)
    paletteMode?: PaletteMode;
    autoK?: number;           // paletteMode==="autoK"일 때 K
    dither?: boolean;         // 디더링 on/off

    mergeTolerance?: number;  // ★ 유사색 병합 임계값(ΔE76). 0이면 병합 안 함.
    seed?: number;            // ★ K-means용 시드(결정론적 결과 보장)

    bgTransparent: boolean;   // 배경 투명 여부
    targetWidth: number;      // 출력 비트맵 폭(px) - 보기용 스케일
    targetHeight: number;     // 출력 비트맵 높이(px)

    showGrid?: boolean;       // 그리드 표시
    gridAlpha?: number;       // 그리드 투명도(0~1)
    outline?: boolean;        // 외곽선 표시
    outlineWeight?: number;   // 외곽선 두께(px)
    seamless?: boolean;       // 이음새 제거(틈/줄 방지)
};

type RGB = { r:number, g:number, b:number };
type LAB = { L:number, a:number, b:number };

// 마지막 색상 매트릭스(다운로드용)
let lastMatrix: string[][] | null = null;

// ===== 워커 메시지 핸들러 =====
self.onmessage = async (e: MessageEvent) => {
    const { type, payload } = e.data || {};
    if (type === "run") {
        const p = payload as RunPayload;
        const res = await runPixelize(p, (prog) => {
            (self as any).postMessage({ type: "progress", value: Math.round(prog) });
        });
        lastMatrix = res.matrix;
        (self as any).postMessage(
            { type: "done", payload: { width: res.width, height: res.height, bitmap: res.bitmap } },
            [res.bitmap] // ImageBitmap을 Transfer
        );
    } else if (type === "export-matrix") {
        (self as any).postMessage({ type: "matrix", payload: lastMatrix ?? [] });
    }
};

// ===== 메인 프로시저: 픽셀 변환 실행 =====
async function runPixelize(p: RunPayload, onProgress: (n:number)=>void) {
    const {
        src, colCount, rowCount, targetWidth, targetHeight, bgTransparent,
        palette, paletteMode="none", autoK=0, dither=false, seamless=false,
        mergeTolerance = 0, seed = 1
    } = p;

    // 원본 픽셀 읽기용 캔버스
    const read = new OffscreenCanvas(src.width, src.height);
    const rctx = read.getContext("2d", { willReadFrequently: true })!;
    rctx.drawImage(src, 0, 0);

    const cellW = src.width / colCount;
    const cellH = src.height / rowCount;

    // 출력 캔버스(미리보기 사이즈)
    const out = new OffscreenCanvas(targetWidth, targetHeight);
    const octx = out.getContext("2d")!;
    octx.imageSmoothingEnabled = false;
    if (!bgTransparent) { octx.fillStyle = "#ffffff"; octx.fillRect(0, 0, targetWidth, targetHeight); }

    const scaleX = targetWidth / colCount;
    const scaleY = targetHeight / rowCount;

    // 시드 기반 의사난수(결정론적 Auto‑K 보장)
    const prng = makePRNG(seed >>> 0);

    // 팔레트 준비
    let palRGB: RGB[] = [];
    if (Array.isArray(palette) && palette.length > 0) {
        palRGB = palette.map(hexToRgb);
    } else if (paletteMode === "autoK" && autoK > 0) {
        palRGB = await buildAutoPaletteK(rctx, src.width, src.height, autoK, prng);
    }

    // 유사색 병합(ΔE76) - 팔레트 정리
    if (palRGB.length > 0 && mergeTolerance > 0) {
        palRGB = mergeSimilarColors(palRGB, mergeTolerance);
    }
    const usePalette = palRGB.length > 0;

    // 결과 색상 매트릭스
    const matrix: string[][] = Array.from({ length: rowCount }, () => Array(colCount).fill("#000000"));

    // 이음새 제거 옵션에 따른 파라미터
    const effGap = seamless ? 0 : (p.gap ?? 0);
    const effRadius = seamless ? 0 : (p.dotRadius ?? 0);

    // --- 변환 루프 ---
    if (usePalette && dither) {
        // 디더링 경로: 원본을 셀 해상도로 축소 후 Floyd–Steinberg 적용
        const low = new OffscreenCanvas(colCount, rowCount);
        const lctx = low.getContext("2d", { willReadFrequently: true })!;
        lctx.drawImage(src, 0, 0, colCount, rowCount);
        const imgData = lctx.getImageData(0, 0, colCount, rowCount);
        const data = imgData.data;

        // Floyd–Steinberg 디더링
        for (let y = 0; y < rowCount; y++) {
            for (let x = 0; x < colCount; x++) {
                const i = (y * colCount + x) * 4;
                const cur = { r: data[i], g: data[i+1], b: data[i+2] };
                const nearest = nearestRGB(cur, palRGB);
                data[i] = nearest.r; data[i+1] = nearest.g; data[i+2] = nearest.b; data[i+3] = 255;

                const err = { r: cur.r - nearest.r, g: cur.g - nearest.g, b: cur.b - nearest.b };
                ditherAt(data, colCount, rowCount, x+1, y  , err, 7/16);
                ditherAt(data, colCount, rowCount, x-1, y+1, err, 3/16);
                ditherAt(data, colCount, rowCount, x  , y+1, err, 5/16);
                ditherAt(data, colCount, rowCount, x+1, y+1, err, 1/16);
            }
            onProgress((y / rowCount) * 40);
        }
        lctx.putImageData(imgData, 0, 0);

        // 셀별 렌더
        for (let r = 0; r < rowCount; r++) {
            for (let c = 0; c < colCount; c++) {
                const { r: R, g: G, b: B } = getPixel(lctx, c, r);
                const hex = rgbaToHex(R, G, B, 255);
                matrix[r][c] = hex;

                // 출력 좌표(정수 스냅)
                const x0 = Math.round(c * scaleX), y0 = Math.round(r * scaleY);
                const x1 = Math.round((c + 1) * scaleX), y1 = Math.round((r + 1) * scaleY);
                const cellPixW = Math.max(1, x1 - x0), cellPixH = Math.max(1, y1 - y0);

                // 셀 채우기(사각형 기본, 반지름>0이면 원형)
                octx.fillStyle = hex;
                if (effRadius > 0) {
                    const innerW = Math.max(1, cellPixW - effGap);
                    const innerH = Math.max(1, cellPixH - effGap);
                    const rad = Math.min(innerW, innerH) / 2;
                    octx.beginPath();
                    octx.arc(x0 + cellPixW / 2, y0 + cellPixH / 2, rad, 0, Math.PI * 2);
                    octx.fill();
                } else {
                    const drawW = seamless ? cellPixW : Math.max(1, cellPixW - effGap);
                    const drawH = seamless ? cellPixH : Math.max(1, cellPixH - effGap);
                    octx.fillRect(x0, y0, drawW, drawH);
                }
            }
            onProgress(40 + (r / rowCount) * 35);
        }
    } else {
        // 일반 경로: 각 셀 평균색 → (옵션) 팔레트 스냅
        for (let r = 0; r < rowCount; r++) {
            for (let c = 0; c < colCount; c++) {
                const x0s = Math.floor(c * cellW), y0s = Math.floor(r * cellH);
                const x1s = Math.min(src.width , Math.floor((c + 1) * cellW));
                const y1s = Math.min(src.height, Math.floor((r + 1) * cellH));
                const ws = Math.max(1, x1s - x0s), hs = Math.max(1, y1s - y0s);

                const block = rctx.getImageData(x0s, y0s, ws, hs).data;
                let rr = 0, gg = 0, bb = 0;
                const count = ws * hs;
                for (let i = 0; i < block.length; i += 4) {
                    rr += block[i]; gg += block[i+1]; bb += block[i+2];
                }
                let R = Math.round(rr / count), G = Math.round(gg / count), B = Math.round(bb / count);

                if (usePalette) {
                    const nearest = nearestRGB({ r: R, g: G, b: B }, palRGB);
                    R = nearest.r; G = nearest.g; B = nearest.b;
                }
                const hex = rgbaToHex(R, G, B, 255);
                matrix[r][c] = hex;

                // 출력 좌표(정수 스냅)
                const x0 = Math.round(c * scaleX), y0 = Math.round(r * scaleY);
                const x1 = Math.round((c + 1) * scaleX), y1 = Math.round((r + 1) * scaleY);
                const cellPixW = Math.max(1, x1 - x0), cellPixH = Math.max(1, y1 - y0);

                // 셀 채우기
                octx.fillStyle = hex;
                if (effRadius > 0) {
                    const innerW = Math.max(1, cellPixW - effGap);
                    const innerH = Math.max(1, cellPixH - effGap);
                    const rad = Math.min(innerW, innerH) / 2;
                    octx.beginPath();
                    octx.arc(x0 + cellPixW / 2, y0 + cellPixH / 2, rad, 0, Math.PI * 2);
                    octx.fill();
                } else {
                    const drawW = seamless ? cellPixW : Math.max(1, cellPixW - effGap);
                    const drawH = seamless ? cellPixH : Math.max(1, cellPixH - effGap);
                    octx.fillRect(x0, y0, drawW, drawH);
                }
            }
            onProgress((r / rowCount) * 75);
        }
    }

    // 공용 격자 좌표(정수 스냅) - 외곽선/그리드 끊김 방지
    const gx = Array.from({ length: colCount + 1 }, (_, c) => Math.round(c * scaleX));
    const gy = Array.from({ length: rowCount + 1 }, (_, r) => Math.round(r * scaleY));

    // 외곽선(경계가 다른 곳만 연속 구간으로 렌더)
    if (p.outline) {
        const w = Math.max(1, Math.floor(p.outlineWeight ?? 1));
        octx.save();
        octx.fillStyle = "#000";

        // 가로 경계(윗선)
        for (let r = 0; r < rowCount; r++) {
            const y = gy[r];
            let segStart = 0, prevDiff = false;
            for (let c = 0; c < colCount; c++) {
                const diff = r > 0 ? (matrix[r][c] !== matrix[r-1][c]) : false;
                if (diff && !prevDiff) segStart = c;
                if ((!diff && prevDiff) || (diff && c === colCount - 1)) {
                    const segEndEx = (!diff && prevDiff) ? c : (c + 1);
                    const x0 = gx[segStart], x1 = gx[segEndEx];
                    if (x1 > x0) octx.fillRect(x0, y, x1 - x0, w);
                }
                prevDiff = diff;
            }
        }

        // 세로 경계(왼선)
        for (let c = 0; c < colCount; c++) {
            const x = gx[c];
            let segStart = 0, prevDiff = false;
            for (let r = 0; r < rowCount; r++) {
                const diff = c > 0 ? (matrix[r][c] !== matrix[r][c-1]) : false;
                if (diff && !prevDiff) segStart = r;
                if ((!diff && prevDiff) || (diff && r === rowCount - 1)) {
                    const segEndEx = (!diff && prevDiff) ? r : (r + 1);
                    const y0 = gy[segStart], y1 = gy[segEndEx];
                    if (y1 > y0) octx.fillRect(x, y0, w, y1 - y0);
                }
                prevDiff = diff;
            }
        }

        octx.restore();
    }

    // 그리드(보조선)
    if (p.showGrid) {
        const a = Math.min(1, Math.max(0, p.gridAlpha ?? 0.25));
        octx.save();
        octx.globalAlpha = a;
        octx.strokeStyle = "#000";
        octx.lineWidth = 1;
        for (let c = 0; c <= colCount; c++) {
            const x = gx[c] + 0.5; // 샤프한 1px 라인
            octx.beginPath(); octx.moveTo(x, 0); octx.lineTo(x, targetHeight); octx.stroke();
        }
        for (let r = 0; r <= rowCount; r++) {
            const y = gy[r] + 0.5;
            octx.beginPath(); octx.moveTo(0, y); octx.lineTo(targetWidth, y); octx.stroke();
        }
        octx.restore();
    }

    const bitmap = await (out as any).transferToImageBitmap();
    return { width: targetWidth, height: targetHeight, bitmap, matrix };
}

// ====== 유틸: 색 변환/거리/디더링 ======
function hexToRgb(hex: string): RGB {
    const s = hex.replace("#", "");
    const n = parseInt(s.length === 3 ? s.split("").map(ch=>ch+ch).join("") : s, 16);
    return { r: (n>>16)&255, g: (n>>8)&255, b: n&255 };
}
function rgbaToHex(r:number,g:number,b:number,_a:number){
    const to2 = (n:number)=>n.toString(16).padStart(2,"0");
    return `#${to2(r)}${to2(g)}${to2(b)}`;
}
function dist2(a:RGB, b:RGB) { const dr=a.r-b.r, dg=a.g-b.g, db=a.b-b.b; return dr*dr + dg*dg + db*db; }
function nearestRGB(c:RGB, pals:RGB[]) {
    let best = pals[0], dmin = Infinity;
    for (const p of pals) { const d = dist2(c, p); if (d < dmin) { dmin = d; best = p; } }
    return best;
}
function clamp8(n:number){ return Math.max(0, Math.min(255, Math.round(n))); }
function ditherAt(data:Uint8ClampedArray, w:number, h:number, x:number, y:number, err:RGB, weight:number){
    if (x<0||x>=w||y<0||y>=h) return;
    const i = (y*w + x)*4;
    data[i  ] = clamp8(data[i  ] + err.r*weight);
    data[i+1] = clamp8(data[i+1] + err.g*weight);
    data[i+2] = clamp8(data[i+2] + err.b*weight);
}
function getPixel(ctx: OffscreenCanvasRenderingContext2D, x:number, y:number): RGB {
    const d = ctx.getImageData(x, y, 1, 1).data;
    return { r: d[0], g: d[1], b: d[2] };
}

// ====== K-means 팔레트(시드 PRNG 주입) ======
function makePRNG(seed: number) {
    // 간단 LCG (Numerical Recipes)
    let s = (seed >>> 0) || 1;
    return {
        next() { s = (1664525 * s + 1013904223) >>> 0; return s; },
        random() { return this.next() / 0x100000000; }, // [0,1)
        int(n: number) { return Math.floor(this.random() * n); } // [0,n)
    };
}

/** 주어진 이미지에서 무작위 샘플링 + K-means로 대표색 K개 추출(결정론적) */
async function buildAutoPaletteK(
    ctx: OffscreenCanvasRenderingContext2D,
    w: number, h: number, K: number,
    prng: ReturnType<typeof makePRNG>
): Promise<RGB[]> {
    const sampleN = Math.min(5000, Math.floor((w*h)/20));
    const pts: RGB[] = [];
    for (let i=0;i<sampleN;i++){
        const x = prng.int(w);
        const y = prng.int(h);
        const d = ctx.getImageData(x, y, 1, 1).data;
        pts.push({ r:d[0], g:d[1], b:d[2] });
    }
    // 초기 중심도 시드 기반으로 고정
    const centers: RGB[] = [];
    for (let k=0;k<K;k++){ centers.push(pts[prng.int(pts.length)]); }

    // 반복(8회 정도면 충분)
    for (let it=0; it<8; it++){
        const acc = Array.from({length:K}, ()=>({r:0,g:0,b:0,c:0}));
        for (const p of pts){
            let bi=0,bd=Infinity;
            for (let k=0;k<K;k++){ const d=dist2(p,centers[k]); if(d<bd){bd=d;bi=k;} }
            acc[bi].r+=p.r; acc[bi].g+=p.g; acc[bi].b+=p.b; acc[bi].c++;
        }
        for (let k=0;k<K;k++){
            if (acc[k].c>0){
                centers[k] = {
                    r: Math.round(acc[k].r/acc[k].c),
                    g: Math.round(acc[k].g/acc[k].c),
                    b: Math.round(acc[k].b/acc[k].c),
                };
            } else {
                centers[k] = pts[prng.int(pts.length)];
            }
        }
    }
    return centers;
}

// ====== 유사색 병합(ΔE76) ======
function mergeSimilarColors(pals: RGB[], de: number): RGB[] {
    if (pals.length <= 1) return pals.slice();
    const labs = pals.map(rgbToLab);
    const picked: number[] = [];
    const used = new Array(pals.length).fill(false);

    for (let i = 0; i < pals.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        // i를 대표로 삼고, ΔE <= de 인 색들을 평균내서 하나로 통합
        let L = labs[i].L, A = labs[i].a, B = labs[i].b, cnt = 1;
        for (let j = i + 1; j < pals.length; j++) {
            if (used[j]) continue;
            if (deltaE76(labs[i], labs[j]) <= de) {
                used[j] = true;
                L += labs[j].L; A += labs[j].a; B += labs[j].b; cnt++;
            }
        }
        const avgLab = { L: L/cnt, a: A/cnt, b: B/cnt };
        picked.push(i);
        const rgb = labToRgb(avgLab);
        pals[i] = rgb;
        labs[i] = avgLab;
    }

    const out: RGB[] = [];
    for (let i = 0; i < pals.length; i++) {
        if (used[i] && picked.includes(i)) out.push(pals[i]);
    }
    return out;
}

// ====== RGB↔Lab + ΔE ======
function rgbToLab(rgb: RGB): LAB {
    const srgbToLinear = (u: number) => {
        const s = u / 255;
        return s <= 0.04045 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    };
    const r = srgbToLinear(rgb.r);
    const g = srgbToLinear(rgb.g);
    const b = srgbToLinear(rgb.b);

    // sRGB D65 → XYZ
    const x = r * 0.4124564 + g * 0.3575761 + b * 0.1804375;
    const y = r * 0.2126729 + g * 0.7151522 + b * 0.0721750;
    const z = r * 0.0193339 + g * 0.1191920 + b * 0.9503041;

    const Xn = 0.95047, Yn = 1.00000, Zn = 1.08883;
    const fx = xyzToLabHelper(x / Xn);
    const fy = xyzToLabHelper(y / Yn);
    const fz = xyzToLabHelper(z / Zn);

    return { L: 116 * fy - 16, a: 500 * (fx - fy), b: 200 * (fy - fz) };
}
function labToRgb(lab: LAB): RGB {
    const fy = (lab.L + 16) / 116;
    const fx = fy + (lab.a / 500);
    const fz = fy - (lab.b / 200);

    const Xn = 0.95047, Yn = 1.00000, Zn = 1.08883;
    const xr = labToXyzHelper(fx), yr = labToXyzHelper(fy), zr = labToXyzHelper(fz);

    const x = xr * Xn, y = yr * Yn, z = zr * Zn;

    // XYZ → linear RGB
    let rl =  3.2404542*x - 1.5371385*y - 0.4985314*z;
    let gl = -0.9692660*x + 1.8760108*y + 0.0415560*z;
    let bl =  0.0556434*x - 0.2040259*y + 1.0572252*z;

    const linearToSrgb = (u: number) => {
        const s = Math.max(0, Math.min(1, u));
        return s <= 0.0031308 ? 12.92*s : 1.055*Math.pow(s, 1/2.4) - 0.055;
    };
    const R = Math.round(linearToSrgb(rl) * 255);
    const G = Math.round(linearToSrgb(gl) * 255);
    const B = Math.round(linearToSrgb(bl) * 255);
    return { r: R, g: G, b: B };
}
function xyzToLabHelper(t: number){ return t > 216/24389 ? Math.cbrt(t) : (841/108)*t + 4/29; }
function labToXyzHelper(t: number){ const t3 = t*t*t; return t3 > 216/24389 ? t3 : (108/841)*(t - 4/29); }
function deltaE76(a: LAB, b: LAB){ const dL=a.L-b.L, da=a.a-b.a, db=a.b-b.b; return Math.sqrt(dL*dL+da*da+db*db); }